	randomSeed(seed);
	webGLCanvas.shader(theShader);
	theShader.setUniform('u_resolution', [width / width, height / height]);
	theShader.setUniform('u_time', millis() / 1000);
	theShader.setUniform('u_mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height]);
	theShader.setUniform('u_tex', bgGraphics);

	webGLCanvas.clear();
	webGLCanvas.rect(-width / 2, -height / 2, width, height);


	if (int(seed) % 2 == 0) {
		for (let i = particles_wave.length - 1; i > 0; i--) {
			if (i < particles_wave.length) {
				particles_wave[i].update();
				particles_wave[i].show(bgGraphics);
				if (particles_wave[i].finished()) {
					particles_wave.splice(i, 1);
				}
			}
		}
