// === Tab: Particle ===
function Particle(x, y, ver) {

	this.x = x;
	this.y = y;
	this.pos = createVector(this.x, this.y);
	this.vel_yoko = createVector(0, random(-0.001, 0.001) / 0.001);
	this.acc_yoko = createVector(0, random(-0.01, 0.01) / random(0.001, 0.005));
	this.vel_tate = createVector(random(-0.01, 0.01) / random(0.001, 0.005), 0);
	this.acc_tate = createVector(random(-0.01, 0.01) / random(0.001, 0.005), 0);
	this.alpha1 = alpha1;
	this.alpha2 = alpha2;
	this.r = mySize / parNum * random(140, 70);
	this.particles2 = [];
	this.color1 = color1;
	this.color2 = color2;
	this.grad = 0;
	this.grad2 = 0;
	this.offset = -random(100) * random(2.0, 1.0);
	this.color_ver = random([1, 2, 3, 4, 5, 6, 7, 8]);
	this.switch = 1;
	this.colorbg = "3f4442-5c5358-202020".split("-").map((a) => "#" + a);
	this.ver = ver;
	this.colorGrass1 = colorGrass1;
	this.colorGrass2 = colorGrass2;
	this.grad_grass = 0;

	this.update = function() {

		color_palette();
		this.color1 = color1;
		this.color2 = color2;
		this.colorGrass1 = colorGrass1;
		this.colorGrass2 = colorGrass2;

		if (this.ver == 4 || this.ver == 6) {
			this.vel_yoko = createVector(0, random(-0.01, 0.01) / 0.1);
			this.acc_yoko = createVector(0, random(-0.01, 0.01) / random(0.1, 0.05));
			this.vel_tate = createVector(random(-1, 1) / random(0.1, 0.5), 0);
			this.acc_tate = createVector(random(-1, 1) / random(0.1, 0.5), 0);
		}

		//ver 1,2,4
		if (this.ver == 1 || this.ver == 2 || this.ver == 4 || this.ver == 5 || this.ver == 6) {
			if (this.r > 200) {
				this.r -= 200;
			} else {
				this.r = mySize / parNum * random(140, 70);
			}
		}
		//ver 3
		if (this.ver == 3) {
			if (this.r > 100) {
				this.r -= 100;
			} else {
				this.r = mySize / parNum * random(40, 70);
			}
		}

		if (frameCount % 2 == 0) {
			this.vel_yoko.add(this.acc_yoko);
			this.pos.add(this.vel_yoko);
		} else {
			this.vel_tate.add(this.acc_tate);
			this.pos.add(this.vel_tate);
		}

		this.alpha2 -= random(1) / 2;
		this.alpha1 += random(1);

	};

	this.show = function(p) {

		p.stroke("#ffffff80");
		p.fill(0);
		p.strokeWeight(1 * random(1));

		p.drawingContext.shadowColor = "#20202040";
		p.drawingContext.shadowOffsetX = 1;
		p.drawingContext.shadowOffsetY = 1;
		p.drawingContext.shadowBlur = 0;
		p.push();
		p.translate(this.pos.x + random(-this.offset, this.offset), this.pos.y - random(-this.offset, this.offset));

		//ver 1
		if (this.ver == 1) {

			this.grad = drawingContext.createLinearGradient(
				0, 0, 0, abs(this.r / 25 - random(-this.offset / 20, this.offset / 20)) / random(0.35, 0.55));
			this.grad.addColorStop(random(0.35, 0.5), str(random(this.colorbg)) + "00");
			this.grad.addColorStop(random(0.85, 0.75), this.color1);
			this.grad.addColorStop(random(0.95, 1), this.color2);
			p.drawingContext.strokeStyle = this.grad;
			p.drawingContext.fillStyle = this.grad;

			if (frameCount % 3 == 0) {
				p.noStroke();
			} else {
				p.noFill();
			}
		}

		//ver 2
		if (this.ver == 2) {
			this.grad = drawingContext.createLinearGradient(
				0, 0, 0, abs(this.r / 25 - random(-this.offset / 20, this.offset / 20)) / random(0.35, 0.55));
			this.grad.addColorStop(random(0.35, 0.5), str(random(this.colorbg)) + "00");
			this.grad.addColorStop(random(0.85, 0.75), this.color1);
			this.grad.addColorStop(random(0.95, 1), this.color2);
			p.drawingContext.fillStyle = this.grad;

			this.grad2 = drawingContext.createLinearGradient(
				0, -abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)), 0, abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)));
			this.grad2.addColorStop(random(0.85, 0.75), "#fafdff00");
			this.grad2.addColorStop(random(0.95, 1), "#ffffff");
			p.drawingContext.strokeStyle = this.grad2;
			if (frameCount % 5 == 0) {
				p.noFill();
			} else {
				p.noStroke();
			}
		}

		//ver 3
		if (this.ver == 3) {
			this.grad = drawingContext.createLinearGradient(
				0, 0, 0, abs(this.r / 25 - random(-this.offset / 20, this.offset / 20)) / random(0.35, 0.55));
			this.grad.addColorStop(random(0.35, 0.5), str(random(this.colorbg)) + "00");
			this.grad.addColorStop(random(0.85, 0.75), this.color1);
			this.grad.addColorStop(random(0.95, 1), this.color2);
			p.drawingContext.fillStyle = this.grad;

			this.grad2 = drawingContext.createLinearGradient(
				0, abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)), 0, -abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)));
			this.grad2.addColorStop(random(0.55, 0.35), "#ffffff00");
			this.grad2.addColorStop(random(0.85, 1), "#ffffff");
			p.drawingContext.strokeStyle = this.grad2;
		}

		//ver 4,6
		if (this.ver == 4 || this.ver == 6) {
			p.drawingContext.shadowColor = "#20202080";
			p.drawingContext.shadowOffsetX = 1;
			p.drawingContext.shadowOffsetY = 1;
			p.drawingContext.shadowBlur = 100;

			this.grad = drawingContext.createLinearGradient(
				0, 0, 0, abs(this.r / 25 - random(-this.offset / 20, this.offset / 20)) / random(0.35, 0.55));
			this.grad.addColorStop(random(0.35, 0.5), str(random(this.colorbg)) + "00");
			this.grad.addColorStop(random(0.85, 0.75), this.color1);
			this.grad.addColorStop(random(0.95, 1), this.color2);
			p.drawingContext.fillStyle = this.grad;

			this.grad2 = drawingContext.createLinearGradient(
				0, -abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)), 0, abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)));
			this.grad2.addColorStop(random(0.85, 0.75), "#fafdff00");
			this.grad2.addColorStop(random(0.95, 1), "#ffffff");
			p.drawingContext.strokeStyle = this.grad2;
			if (frameCount % 5 == 0) {
				p.noFill();
			} else {
				p.noStroke();
			}
		}

		//ver 5
		if (this.ver == 5) {
			p.drawingContext.shadowColor = "#20202080";
			p.drawingContext.shadowOffsetX = 1;
			p.drawingContext.shadowOffsetY = 1;
			p.drawingContext.shadowBlur = 0;

			this.grad = drawingContext.createLinearGradient(
				0, 0, 0, abs(this.r / 25 - random(-this.offset / 20, this.offset / 20)) / random(0.35, 0.55));
			this.grad.addColorStop(random(0.35, 0.5), str(random(this.colorbg)) + "00");
			this.grad.addColorStop(random(0.85, 0.75), this.color1);
			this.grad.addColorStop(random(0.95, 1), this.color2);
			p.drawingContext.fillStyle = this.grad;

			this.grad2 = drawingContext.createLinearGradient(
				0, -abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)), 0, abs(this.r / 25 / 0.5 - random(-this.offset / 10, this.offset / 50)));
			this.grad2.addColorStop(random(0.35, 0.5), str(random(this.colorbg)) + "00");
			this.grad2.addColorStop(random(0.85, 0.75), this.color1);
			this.grad2.addColorStop(random(0.95, 1), this.color2);
			p.drawingContext.strokeStyle = this.grad2;

			p.strokeWeight(5 * random(1));
			if (frameCount % 5 == 0) {
				p.noStroke();
			} else {
				p.noFill();
			}
		}


		p.ellipseMode(CORNER);
		p.rotate(PI);
		p.ellipse(0, 0, (this.r / 25 - random(-this.offset / 20, this.offset / 20)) / 1, -(this.r / 10 - random(-this.offset / 20, this.offset / 20)) / 1.25);

		//ver 6
		if (this.ver == 6 && frameCount % 5 != 0) {
			noStroke();
			this.grad_grass = drawingContext.createLinearGradient(
				0, 0, 0, abs(this.r / 25 - random(-this.offset / 20, this.offset / 20)) / random(0.35, 0.55));
			this.grad_grass.addColorStop(random(0.85, 0.92), str(random(this.colorbg)) + "00");
			this.grad_grass.addColorStop(random(0.95, 0.92), this.colorGrass1);
			this.grad_grass.addColorStop(random(0.99, 1), this.colorGrass2);
			p.drawingContext.fillStyle = this.grad_grass;
			p.ellipse(0, 0, (this.r / 25 - random(-this.offset / 20, this.offset / 20)) / 1, -(this.r / 10 - random(-this.offset / 20, this.offset / 20)) / 1.25);
		}

		p.pop();

	};

	this.finished = function() {
		return this.alpha2 < 20;
	};
}

